const PlotAreaRectangle = () => {
  const plotArea: PlotArea | undefined = usePlotArea();
  const theme = useRechartsTheme();
  if (plotArea == null) {
    return null;
  }
  return (
    <Rectangle
      x={plotArea.x}
      y={plotArea.y}
      width={plotArea.width}
      height={plotArea.height}
      stroke={theme?.typography?.color ?? 'black'}
      fill="none"
    />
  );
};

